const changeScore = (them , amount) => {
    if (!them) return
        them.skill.score += amount;
};
const healer = (me, them, multiplier) => {
    if (!them) return
    if (them.team == me.team && them.type == 'tank' && them.name != "Sanctuary") {
        //me.damage *= me.damage * multiplier * -1;
        them.health.amount = them.health.amount + me.damage * multiplier
        them.shield.amount = them.shield.amount + me.damage * multiplier
    if(them.health.amount < them.health.max) {
        changeScore(me.master , me.damage*multiplier*10)
        }
        //them.team = me.team
        //me.body.skill.score = me.body.skill.score + me.damage + 10//to fix
    }
}
const exploiter = (me, them, multiplier, chance) => {
    if (!them) return
    if (Math.floor(Math.random() * 101) + 1 < chance && them.variables.poisoned && !them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode) {
        me.damage *= multiplier * 2;
        me.source.sendMessage('Target exploited!');
        them.sendMessage("You've got exploited by " + me.source.name);
    }
};

const drunk = (me, them, duration, intensity) => {
    if (!them) return
        if (!them.immuneToAbilities  && !them.invuln && !them.passive && !them.godmode && !them.variables.drunk) {
        them.variables.drunk = true
        //them.SPEED = -them.SPEED
        //them.ACCELERATION = -them.ACCELERATION
        //them.refreshBodyAttributes()
        timer(() => {
            if (them.variables.drunk) {
                them.velocity.x = (-1 * ((Math.random() - 0.5) * 2) * them.SPEED * intensity)
                them.velocity.y = (-1 * ((Math.random() - 0.5) * 2) * them.SPEED * intensity)
            }
        }, 3 * duration);
       // setTimeout((them.SPEED = -them.SPEED, them.ACCELERATION = -them.ACCELERATION , them.variables.drunk = false,   them.refreshBodyAttributes()), 3 * duration * 1000)}
       setTimeout(() => {them.variables.drunk = false}, 3* duration*1000)
}};
const crit = (me, them, multiplier, chance) => {
    if (!them) return
    if (Math.floor(Math.random() * 101) + 1 < chance && (them.type == 'tank' || them.type == 'miniboss')) {
        me.damage *= multiplier * 2;
        me.source.sendMessage('Crit landed!');
        them.sendMessage(me.source.name + ' landed a critical hit on you!');
    }
};

const ice = (them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode) timer(() => {
        them.velocity.x /= 1.05 * multiplier;
        them.velocity.y /= 1.05 * multiplier;
    }, 1.5 * duration);
};
const flu = (me, them, multiplier, duration, team) => {
    if (!them && !me.isDead()) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && them.team != team && !them.variables.flu) {
        let oddu = them.onDealtDamageUniv || (() => { });
        ice(them, multiplier, duration);
        them.variables.flu = true;
        them.onDealtDamageUniv = (me2, them2) => {
            if (me2 && them2) {
                if (oddu) oddu();
                flu(me2, them2, 1, 1, team);
            }
        }
        setTimeout(() => {
        them.velocity.x /= 1.05 * multiplier;
        them.velocity.y /= 1.05 * multiplier;
    }, 1.5 * duration);
    if (!them.variables.flu) {
        flu(me2, them2, 1, 0, team);
        flu(me, them, 1, 0, team);
    }
  }
};
const poison = (me, them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.poisoned) {
        them.variables.poisoned = true;
        setTimeout(() => {
            them.variables.poisoned = false;
        }, 2 * duration * 1000);
        timer(() => {
            if (them.variables.poisoned && them.health.amount > 10) {
                them.health.amount -= multiplier * 0.5;
                if (them.onDamaged) them.onDamaged(them, me, multiplier * 0.5)
                if (me.onDealtDamage) me.onDealtDamage(me, them.multiplier * 0.5)
                if (me.onDealtDamageUniv) me.onDealtDamageUniv(me, them.multiplier * 0.5)
            }
        }, 2 * duration);
    }
};
