const makeAutoN = (type, sides = 3, name, options = {}) => {
    let output = deepCopy(type),
        stats = options.stats || [g.blank],
        swivel = options.swivel,
        turretName = makeExportName(type, `AutoN${swivel ? 'Swivel' : ''}`, [stats]);

    if (!defExports[turretName]) {
        defExports[turretName] = deepCopy(type);
        applyStats(defExports[turretName].GUNS, [g.auto, ...stats, swivel ? [1.5, 1, 1, 1, .81, .765, .9, 1, 1, 1, 1, 1, 1] : g.blank]);
    };

    if (type.DANGER + sides - 1 < 7) output.DANGER += sides - 1;
    output.LABEL = name || `${output.LABEL}-${sides}`;
    output.FACING_TYPE = 'autospin';
    output.GUNS = [];
    output.PROPS = [];
    output.TURRETS = ((out = []) => {
        for (let i = 0; i < sides; i++) out.push({
            POSITION: [swivel ? 8 * (Math.pow(Math.sqrt(.625, 4), sides - 3)) + 1 : 10 * (Math.pow(Math.sqrt(.78, 4), sides - 3)) + 1, swivel ? 7 : 9, 0, 360 / sides * i, swivel ? 360 : 360 / sides + 65, swivel ? 1 : 0],
            TYPE: [defExports[turretName], {
                LABEL: '',
                BODY: {
                    FOV: 2.5
                },
                CONTROLLERS: ['canRepel', 'onlyAcceptInArc', 'mapAltToFire', 'nearestDifferentMaster'],
                COLOR: options.color || 16
            }]
        });
        return out;
    })();
    return output;
};
const makeMultiplicativePrefix = (n) => {
    switch (n) {
        case 2:
            return "Double"
        case 3:
            return "Triple"
        case 4:
            return "Quadruple"
        case 5:
            return "Quintuple"
        case 6:
            return "Sextuple"
        case 7:
            return "Septuple"
        case 8:
            return "Octuple"
        case 9:
            return "Nonuple"
        case 10:
            return "Decuple"
        case 11:
            return "Undecuple"
        case 12:
            return "Duoecuple"
        default:
            return toString(n)+"-uple"
    }
};
