function tapeTanksTogether(frontType, rearType, name, options = {}) {
  ///Alt fire arguments are busted but the main function works
  let output = JSON.parse(JSON.stringify(frontType)),
    tempRearType = JSON.parse(JSON.stringify(rearType));

  if (!frontType.GUNS) output.GUNS = [];
  if (!rearType.GUNS) tempRearType.GUNS = [];

  let //Set options based on options provided, or use defaults if none are provided
    rearAltFire = options.rearAltFire ? options.rearAltFire : false;

  for (let i = 0; i < tempRearType.GUNS.length; i++) {
    tempRearType.GUNS[i].POSITION[5] += 180;
    if (tempRearType.GUNS[i].PROPERTIES)
      tempRearType.GUNS[i].PROPERTIES.TYPE = rearType.GUNS[i].PROPERTIES.TYPE;
  }

  if (rearAltFire)
    tempRearType.GUNS.forEach((gun) => {
      if (gun.PROPERTIES) gun.PROPERTIES.ALT_FIRE = true;
    });

  if (frontType.DANGER != null)
    output.DANGER = Math.abs((frontType.DANGER + tempRearType.DANGER) / 2);
  if (frontType.TURRETS != null) output.TURRETS = frontType.TURRETS;
  output.GUNS = [...tempRearType.GUNS, ...frontType.GUNS];
  output.LABEL =
    name == null ? frontType.LABEL + " taped to " + tempRearType.LABEL : name;
  output.STAT_NAMES = statNames.generic;
  return output;
}
const makeSidekick = (type, name, statSet = [g.blank]) => {
    let output = deepCopy(type),
        sidekick = newExport(`${output.LABEL || ''}Sidekick`);

    statSet = statSet || [g.blank];
    output.GUNS = output.GUNS || [];
    defExports[sidekick] = deepCopy(defExports.minion);
    defExports[sidekick].GUNS = deepCopy(output.GUNS);
    applyStats(defExports[sidekick].GUNS, [g.minion, ...statSet]);
    output.GUNS.push({
        POSITION: [4.5, 10, 1, 10.5, 0, 180, 0]
    }, {
        POSITION: [1, 12, 1.01, 15, 0, 180, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.factory, g.baby_factory, g.weak]),
            TYPE: [defExports[sidekick], {
              INDEPENDENT: true
            }],
            STAT_CALCULATOR: gunCalcNames.drone,
            AUTOFIRE: true,
            SYNCS_SKILLS: true,
            MAX_CHILDREN: 3,
        }
    }, {
        POSITION: [3.5, 12, 1, 8, 0, 180, 0]
    });
    output.DANGER = output.DANGER < 6 ? output.DANGER + 2 : 7;
    output.LABEL = name || `Sidekick ${output.LABEL}`;
    return output;
};
const makeFlank = (type, sides = 3, name, options = {}) => {
    let output = deepCopy(type),
        reloadDelay = options.reload_delay || new Array(sides),
        stats = options.stats || [g.blank],
        angles = options.angles || new Array(sides);

    applyStats(output.GUNS, [g.flank, ...stats]);

    let baseGuns = deepCopy(output.GUNS);
    output.GUNS = [];
    for (let i = 0; i < sides; i++) {
        for (let j = 0; j < baseGuns.length; j++) {
            let outputGun = deepCopy(baseGuns[j]);
            outputGun.POSITION[5] += angles[i] == undefined ? 360 / sides * i : angles[i];
            if (reloadDelay[i] != undefined) outputGun.POSITION[6] += reloadDelay[i];
            output.GUNS.push(outputGun);
        }
    }
    if (output.DANGER < 7) output.DANGER++;
    output.LABEL = name || `Flank ${output.LABEL}`;
    return output;
};
const makePara = (x, yy, name, options = {}) => {
    if (options.c == null) options.c = 50;
    if (options.mul == null) options.mul = 2;
    if (options.cycle == null) options.cycle = 360;
    if (options.stat == null) options.stat = g.blank;
    let bullet = deepCopy(defExports.bullet);
    bullet.GUNS = [];
    bullet.MOTION_TYPE = 'stopOnDeath';
    for (let i = 0; i < options.cycle; i += options.cycle / options.c) {
        let ex = eval(x),
            ey = eval(yy),
            spd = Math.hypot(ex, ey) * options.mul;
        bullet.GUNS.push({
            POSITION: [0, 18, 1, 10, 0, Math.atan2(ey, ex) * (180 / Math.PI), 1e99],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([
                    [66, 1, .0000001, .25, 1, .07, 5, spd, spd, 2, 1, .0000001, 1], options.stat
                ]),
                TYPE: [defExports.bullet, {
                    PERSISTS_AFTER_DEATH: true
                }],
                LABEL: gunCalcNames.thruster,
                SHOOT_ON_DEATH: true
            }
        })
    };
    return {
        PARENT: [defExports.genericTank],
        LABEL: name || 'Parametric',
        GUNS: [{
            POSITION: [18, 8, 1, 0, 0, 0, 0],
            PROPERTIES: {
                SHOOT_SETTINGS: combineStats([
                    [66, 0, .1, 1, .0002, .2, 1, .000045, 2, 0, 1, 15, 1]
                ]),
                TYPE: bullet
            }
        }, {
            POSITION: [19, 3, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: options.color || 25
            }
        }]
    };
};
