const neoMakeAnimTank = (exportName, tankName, tanks, options = {}) => {
    let animLength = options.animLength || 31,
        hasProp = options.hasProp == undefined ? true : options.hasProp,
        duration = options.duration || 20,
        tankInfo = options.tankInfo || {};
    let prop = (color) => {
        return {
            POSITION: [14, 3.5, 1, 0, 0, 0, 0],
            PROPERTIES: {
                COLOR: color
            }
        }
    };

    for (let i = 0; i < tanks.length; i++) {
        let frameName = `${exportName}${i * animLength}`,
            secondOfTwo = (tanks.length == 2 && i == 1);

        defExports[frameName] = { ...deepCopy(tanks[i].tank), ...tankInfo };
        defExports[frameName].LABEL = tanks[i].name || tankName;
        defExports[frameName].GUNS = defExports[frameName].GUNS || [];
        defExports[frameName].TURRETS = defExports[frameName].TURRETS || [];

        if (tanks[i].skip) {
            applyStats(defExports[frameName].GUNS, [g.blank], {
                shootEdit: ((prop) => {
                    prop.CAN_SHOOT = false;
                })
            });
            for (let turret of defExports[frameName].TURRETS) {
                turret.TYPE = [turret.TYPE, {
                    INDEPENDENT: true,
                    CONTROLLERS: []
                }]
            }
            defExports[frameName].ON_DEFINED = (me, entities) => {
                animate(me, exportName, animLength, tanks[i].duration || duration, secondOfTwo ? false : true, secondOfTwo ? 0 : i * animLength, entities, !secondOfTwo && i == tanks.length - 1 ? true : false);
            };
        } else {
            defExports[frameName].ON_ALT = (me, entities) => {
                animate(me, exportName, animLength, tanks[i].duration || duration, secondOfTwo ? false : true, secondOfTwo ? 0 : i * animLength, entities, !secondOfTwo && i == tanks.length - 1 ? true : false);
            };
        }
        if (hasProp) defExports[frameName].GUNS.push(prop(245 + 31 * (Math.floor(i * animLength / (tanks.length - 1))) / animLength));
    }

    for (let tankNumber = 0; tankNumber < tanks.length; tankNumber++) {
        for (let animIndex = 1; animIndex < animLength; animIndex++) {
            let frameName = `${exportName}${tankNumber * animLength + animIndex}`,
                tankA = tanks[tankNumber],
                tankB = tanks[(tankNumber + 1) % tanks.length];

            defExports[frameName] = {
                ...{
                    PARENT: [defExports.genericTank],
                    LABEL: tankName,
                    STAT_NAMES: statNames.generic,
                    GUNS: ((out = []) => {
                        let gunsA = tankA.guns || tankA.tank.GUNS || [],
                            gunsB = tankB.tank.GUNS || [];

                        for (let gunIndex = 0; gunIndex < Math.max(gunsA.length, gunsB.length); gunIndex++) {
                            let gunA = gunsA[gunIndex],
                                gunB = gunsB[gunIndex];
                            if (gunA && gunB) out.push({
                                POSITION: ((out2 = []) => {
                                    for (let posIndex = 0; posIndex < 7; posIndex++){
                                      out2.push(gunA.POSITION[posIndex] * (animLength - animIndex) / animLength + gunB.POSITION[posIndex] * animIndex / animLength);
                                    }
                                    return out2;
                                })(),
                                PROPERTIES: {
                                  COLOR: gunA?.PROPERTIES?.COLOR,
                                  SKIN: gunA?.PROPERTIES?.SKIN
                                }
                            });
                            else if (gunA) out.push({
                                POSITION: ((out2 = []) => {
                                    for (let posIndex = 0; posIndex < 7; posIndex++) out2.push(gunA.POSITION[posIndex] * (animLength - animIndex) / animLength);
                                    return out2;
                                })()
                            });
                            else if (gunB) out.push({
                                POSITION: ((out2 = []) => {
                                    for (let posIndex = 0; posIndex < 7; posIndex++) out2.push(gunB.POSITION[posIndex] * animIndex / animLength);
                                    return out2;
                                })()
                            });
                        }

                        if (hasProp) {
                            if (tankNumber == tanks.length - 1) {
                                out.push(prop(276 - Math.floor(31 * animIndex / animLength)));
                            } else out.push(prop(245 + Math.floor(31 * animIndex / animLength / (tanks.length - 1)) + Math.floor(31 * tankNumber / (tanks.length - 1))));
                        }

                        return out;
                    })(),
                    TURRETS: ((out = []) => {
                        let turretsA = tankA.turrets || tankA.tank.TURRETS || [],
                            turretsB = tankB.tank.TURRETS || [];

                        for (let turretIndex = 0; turretIndex < Math.max(turretsA.length, turretsB.length); turretIndex++) {
                            let turretA = turretsA[turretIndex],
                                turretB = turretsB[turretIndex];

                            if (turretA && turretB) out.push({
                                POSITION: ((out2 = []) => {
                                    for (let posIndex = 0; posIndex < 4; posIndex++) out2.push(turretA.POSITION[posIndex] * (animLength - animIndex) / animLength + turretB.POSITION[posIndex] * animIndex / animLength);
                                    out2.push(0, turretA.POSITION[5]);
                                    return out2;
                                })(),
                                TYPE: [turretA.TYPE, {
                                    INDEPENDENT: true,
                                    CONTROLLERS: []
                                }]
                            });
                            else if (turretA) out.push({
                                POSITION: ((out2 = []) => {
                                    for (let posIndex = 0; posIndex < 4; posIndex++) out2.push(turretA.POSITION[posIndex] * (animLength - animIndex) / animLength);
                                    out2.push(0, turretA.POSITION[5]);
                                    return out2;
                                })(),
                                TYPE: [turretA.TYPE, {
                                    INDEPENDENT: true,
                                    CONTROLLERS: []
                                }]
                            });
                            else if (turretB) out.push({
                                POSITION: ((out2 = []) => {
                                    for (let posIndex = 0; posIndex < 4; posIndex++) out2.push(turretB.POSITION[posIndex] * animIndex / animLength);
                                    out2.push(0, turretB.POSITION[5]);
                                    return out2;
                                })(),
                                TYPE: [turretB.TYPE, {
                                    INDEPENDENT: true,
                                    CONTROLLERS: []
                                }]
                            });
                        }

                        return out;
                    })(),
                    IS_USED: true
                }, ...tankInfo
            };
        }

        if (tanks.length == 2) break;
    }
};
const makeAnimTankBest = (exportName, label, tanks, frames=16, duration=1000, saveChildren=true) => {
    if(!label){ throw new Error("Missing label for animation") }
    if(!exportName){ throw new Error("Missing exportName for animation") }
    if(tanks.length <= 1){ throw new Error("Cannot make animation with 1 or less tanks")}
    let frameCounter = 0
    for (let i = 0; i < tanks.length; i++){
        if(!tanks[i]){ throw new Error("Error while making animation tank. Make sure this function is used below all the used tanks defExports.", tanks[i]) }

        let tank = deepCopy(tanks[i])

        if(i===0){
            defExports[exportName] = deepCopy(tank)
            defExports[exportName].TOOLTIP = "Press Q to switch tanks"
            defExports[exportName+"0"] = tank
            defExports[exportName].LABEL = tank.LABEL = label
            tank.ON_Q = (me) => {
                if (!saveChildren && me.childrenMap) me.childrenMap.forEach(child => child.destroy())
                me.define(Class[`${exportName}1`])
            };

            defExports[exportName].ON_DEFINED = (me) =>{ if(me.isAlive())me.define(Class[exportName+"0"]) }
        }

        let nextTank = deepCopy(tanks[i+1] || tanks[0])

        for(let frame = 0; frame < frames; frame++){
            frameCounter++
            let frameName = `${exportName}${frameCounter}`
            defExports[frameName] = deepCopy(frame+1===frames?nextTank:tank)
            defExports[frameName].TOOLTIP = undefined
            defExports[frameName].LABEL = label
            defExports[frameName].GUNS = []
            defExports[frameName].TURRETS = []
            defExports[frameName].PROPS = []

            let lerpStep = (frame + 1) / frames

            // Hide our current guns
            if (lerpStep !== 1 && tank.GUNS) {
                for (let gun of tank.GUNS) {
                    gun = deepCopy(gun)
                    if (gun.PROPERTIES) gun.PROPERTIES.CAN_SHOOT = false
                    if (gun.POSITION) {
                        for (let gunPosIndex = 0; gunPosIndex < gun.POSITION.length; gunPosIndex++) {
                            gun.POSITION[gunPosIndex] = lerp(gun.POSITION[gunPosIndex], 0, lerpStep)
                        }
                    }
                    defExports[frameName].GUNS.push(gun)
                }
            }
            // Show our new guns
            if (nextTank.GUNS) {
                for (let gun of nextTank.GUNS) {
                    gun = deepCopy(gun)
                    if (frameCounter % frames !== 0 && gun.PROPERTIES) gun.PROPERTIES.CAN_SHOOT = false
                    if (gun.POSITION) {
                        for (let gunPosIndex = 0; gunPosIndex < gun.POSITION.length; gunPosIndex++) {
                            gun.POSITION[gunPosIndex] = lerp(0, gun.POSITION[gunPosIndex], lerpStep)
                        }
                    }
                    defExports[frameName].GUNS.push(gun)
                }
            }

            // Hide our current turrets
            if (lerpStep !== 1 && tank.TURRETS) {
                for (let turret of tank.TURRETS) {
                    turret = deepCopy(turret)
                    if (turret.TYPE) turret.TYPE = [turret.TYPE, { INDEPENDENT: true, CONTROLLERS: [] }]
                    if (turret.POSITION) {
                        for (let turretPosIndex = 0; turretPosIndex < turret.POSITION.length-1; turretPosIndex++) {
                            turret.POSITION[turretPosIndex] = lerp(turret.POSITION[turretPosIndex], 0, lerpStep)
                        }
                    }
                    defExports[frameName].TURRETS.push(turret)
                }
            }
            // Show our new turrets
            if (nextTank.TURRETS) {
                for (let turret of nextTank.TURRETS) {
                    turret = deepCopy(turret)
                    if (frameCounter % frames !== 0 && turret.TYPE) turret.TYPE = [turret.TYPE, { INDEPENDENT: true, CONTROLLERS: [] }]
                    if (turret.POSITION) {
                        for (let turretPosIndex = 0; turretPosIndex < turret.POSITION.length-1; turretPosIndex++) {
                            turret.POSITION[turretPosIndex] = lerp(0, turret.POSITION[turretPosIndex], lerpStep)
                        }
                    }
                    defExports[frameName].TURRETS.push(turret)
                }
            }

            // Hide our current props
            if (lerpStep !== 1 && tank.PROPS) {
                for (let prop of tank.PROPS) {
                    prop = deepCopy(prop)
                    if (prop.POSITION) {
                        for (let propPosIndex = 0; propPosIndex < prop.POSITION.length-1; propPosIndex++) {
                            prop.POSITION[propPosIndex] = lerp(prop.POSITION[propPosIndex], 0, lerpStep)
                        }
                    }
                    defExports[frameName].PROPS.push(prop)
                }
            }
            // Show our new props
            if (nextTank.PROPS) {
                for (let prop of nextTank.PROPS) {
                    prop = deepCopy(prop)
                    if (prop.POSITION) {
                        for (let propPosIndex = 0; propPosIndex < prop.POSITION.length-1; propPosIndex++) {
                            prop.POSITION[propPosIndex] = lerp(0, prop.POSITION[propPosIndex], lerpStep)
                        }
                    }
                    defExports[frameName].PROPS.push(prop)
                }
            }
        }
    }
    for(let i = 1; i < frameCounter+1; i++){
        if (i%frames === 0){// A stopping point to play as that tank
            if (i / frames === tanks.length){ // Last frame
                defExports[`${exportName}${i}`].ON_DEFINED = (me, entities) => {
                    if (me.isAlive()) {
                        me.define(Class[exportName+"0"])
                    }
                };
                return;
            }

            defExports[`${exportName}${i}`].ON_Q = (me) => {
                if(!saveChildren && me.childrenMap) me.childrenMap.forEach(child=>child.destroy())
                me.define(Class[`${exportName}${i + 1}`])
            };
            i++
        };
        
        // Filler frames
        defExports[`${exportName}${i}`].ON_DEFINED = (me, entities) => {
            setTimeout(() => {
                if (me.isAlive()) {
                    me.define(Class[`${exportName}${i + 1}`])
                }
            }, duration / frames)
        };
        defExports[`${exportName}${i}`].ON_Q = undefined
        defExports[`${exportName}${i}`].ON_ALT = undefined
        defExports[`${exportName}${i}`].ON_NOT_ALT = undefined
        defExports[`${exportName}${i}`].ON_MAIN = undefined
        defExports[`${exportName}${i}`].ON_NOT_MAIN = undefined
        defExports[`${exportName}${i}`].ON_KILL = undefined
        defExports[`${exportName}${i}`].ON_DAMAGED = undefined
        defExports[`${exportName}${i}`].ON_TICK = undefined
        defExports[`${exportName}${i}`].ON_FIRE_UNIVERSAL = undefined
        defExports[`${exportName}${i}`].displayText = ""
    }
}
