const diep2arras = (arr) => {
    let borderWidth = 5; // Very specific value
    let scale = 100 / (100 - borderWidth) * 20 / 100;

    return [
        (arr[0] - borderWidth / 2) * scale,  // Size / Length
        (arr[1] * 42 - borderWidth) * scale, // Width
        arr[2],                              // Aspect, 1.75 by default
        arr[3] * scale,                      // Y
        arr[4] * scale,                      // X
        arr[5],                              // Angle
        arr[6]                               // Delay
    ]
};
