function genXmasThings() {
    const sporulatorTurrets = []
    for (let i = 0, min = -8, max = 8; i < 5; i++) {
        sporulatorTurrets.push({
            POSITION: [
                (Math.random() * 2 | 0) + 2,
                Math.floor(Math.random() * (max - min + 1) + min),
                Math.floor(Math.random() * (max - min + 1) + min),
                0, 0, 1
            ],
            TYPE: i > 2 ? defExports.xmasBall : [defExports.xmasBall, {COLOR: 13}]
        })
    }
    return sporulatorTurrets
}
