const lowPen = (me, them) => {
    if (!them) return
    if (!them.invuln && !them.passive && !them.godmode) {
        them.velocity.x -= Math.sin((7 / (them.SIZE / 12)) * them.velocity.direction - me.x);
        them.velocity.y -= Math.cos((7 / (them.SIZE / 12)) * them.velocity.direction - me.y);
    };
};
