        MAX_CHILDREN: options.maxChildren ?? 6,
        DESTROY_OLDEST_CHILD: true,
        SHOOT_SETTINGS: combineStats([g.trap, g.block, g.engineer, ...options.stats]),
        TYPE: options.pillbox || defExports.pillbox,
