const expose = (me, them, level, duration) =>  {
    if(them.team !== me.team && !them.godmode && !them.passive && !them.variables.exposed) {
        them.variables.exposed = true;
        setTimeout(() => {
            them.variables.exposed = false;
        }, 3000 * duration);
    }
    if (them.variables.exposed && them.alpha < 5/10) {
        them.alpha += .5 * level;
        setTimeout(() => {
            them.alpha -= .5 * level;
        }, 3000 * duration);
    }
};
