function branch(exportName, name, tanks, parent = "developer_parent", tier = "UPGRADES_TIER_4", noSpeed = false) {
    const splits = [
        []
    ];
    for (let i = 0; i < tanks.length; i++) {
        if (!tanks[i]) {
            console.log("Branch", name, "found undefined at index", i);
            continue;
        }
        splits[splits.length - 1].push(tanks[i]);
        if (splits[splits.length - 1].length >= 14 && splits.flat().length < tanks.length) {
            splits.push([]);
        }
    }
    for (let i = 0; i < splits.length; i++) {
        defExports[`${exportName}${i === 0 ? "" : i}`] = {
            PARENT: [defExports[parent]],
            LABEL: name + (i > 0 ? ` Page ${i + 1}` : ""),
            BODY: {
                SPEED: noSpeed ? 0 : undefined,
                ACCELERATION: noSpeed ? 0 : undefined
            }
        };
        defExports[`${exportName}${i === 0 ? "" : i}`][tier] = splits[i];
    }
    for (let i = 0; i < splits.length; i++) {
        if (defExports[`${exportName}${i + 1}`] != null) {
            defExports[`${exportName}${i === 0 ? "" : i}`][tier].push(defExports[`${exportName}${i + 1}`]);
            //defExports[`${exportName}${i === 1 ? "" : i}`][tier].push(defExports[`${exportName}${i - 1}`]);
        }
        if (defExports[`${exportName}${i - 1}`] != null) {
            defExports[`${exportName}${i === 0 ? "" : i}`][tier].push(defExports[`${exportName}${i - 1}`]);
            //defExports[`${exportName}${i === 1 ? "" : i}`][tier].push(defExports[`${exportName}${i - 1}`]);
        }
        if(i == 1) {defExports[`${exportName}${i}`][tier].push(defExports[exportName])}
        //if(i == 2) {defExports[`${exportName}${i}`][tier].push(defExports[`${exportName}${1}`])};
    }
}
