function createCrasher(name, options = {}) {
    return {
        TYPE: "crasher",
        LABEL: name || "Crasher",
        VALUE: 25 * (options.value ?? 1),
        COLOR: options.color ?? 5,
        SHAPE: options.shape ?? 3,
        SIZE: options.size ?? 5,
        VARIES_IN_SIZE: true,
        HEALTH_WITH_LEVEL: false,
        CONTROLLERS: ['nearestDifferentMaster', 'mapTargetToGoal'],
        AI: {
            NO_LEAD: true
        },
        BODY: {
            SPEED: 5 * (options.speed ?? 1),
            ACCELERATION: 1.4 * (options.acceleration ?? 1),
            HEALTH: 2 * (options.health ?? 1),
            DAMAGE: 4.5 * (options.damage ?? 1),
            PENETRATION: 2 * (options.penetration ?? 1),
            PUSHABILITY: .5 * (options.pushability ?? 1),
            DENSITY: 10 * (options.density ?? 1),
            RESIST: 2 * (options.resist ?? 1)
        },
        MOTION_TYPE: "motor",
        FACING_TYPE: "smoothWithMotion",
        HITS_OWN_TYPE: "hard",
        HAS_NO_MASTER: true,
        DRAW_HEALTH: true,
        GUNS: [],
        TURRETS: []
    };
}

