defExports.hewnPellet360 = {
    PARENT: [defExports.genericTank],
    LABEL: '360-Hewn Pelleter',
    DANGER: 7,
    BODY: {
        SPEED: base.SPEED * .95,
        ACCELERATION: base.ACCEL * .7
    },
    GUNS: []
};
for (let i = 0; i < 60; i++) {
    let angle = i * 6;
    defExports.hewnPellet360.GUNS = defExports.hewnPellet360.GUNS.concat({
        POSITION: [17, 2, 1, 0, 3, angle, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.twin, g.pure_gunner, g.faster, g.pellet, g.flank]),
            TYPE: defExports.bullet
        }
    }, {
        POSITION: [17, 1.95, 1, 0, -3, angle, .5],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.twin, g.pure_gunner, g.faster, g.pellet, g.flank]),
            TYPE: defExports.bullet
        }
    }, {
        POSITION: [17, 1.95, 1, -2.7, 2, 22.5 + angle, .5],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.twin, g.pure_gunner, g.fast, g.more_reload, g.flank]),
            TYPE: defExports.bullet
        }
    }, {
        POSITION: [17, 2, 1, -2.7, -2, -22.5 + angle, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.twin, g.pure_gunner, g.fast, g.more_reload, g.flank]),
            TYPE: defExports.bullet
        }
    }, {
        POSITION: [4.5, 8.5, -1.6, 7.5, 0, angle, 0]
    });
}
