const blast = (them, multiplier, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode) timer(() => {
        them.accel.x -= Math.sin((3 / (them.SIZE / 12)) * them.velocity.direction) * multiplier;
        them.accel.y -= Math.cos((3 / (them.SIZE / 12)) * them.velocity.direction) * multiplier;
    }, 1.5 * duration);
};
