const discom = (them, duration) => {
if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && them.facingType === 'toTarget') timer(() => {
        them.facingType = 'discom';
        setTimeout(() => {
            them.facingType = 'toTarget';
        }, 4 * duration * 1000);
    }, 1.5 * duration);
};
