for (let i = 0; i < 30; i++) defExports.implodeProjectile.GUNS.push({
    POSITION: [i > 10 ? 2 : 7, 3.5, 1, -340, 0, i > 10 ? i * 20 : i * 18, 99],
    PROPERTIES: {
        SHOOT_SETTINGS: combineStats([g.basic, g.less_power]),
        TYPE: [defExports.bullet, {
            PERSISTS_AFTER_DEATH: true,
            ON_DEALT_DAMAGE: (me, them) => {
                if (them.team !== me.team && !them.immuneToAbilities && !them.settings.ratioEffects && !them.godmode && !them.passive && them.density > 12)
                them.velocity.x += me.velocity.x / (them.SIZE / 12);
                them.velocity.y += me.velocity.y / (them.SIZE / 12);
            }
        }],
        SHOOT_ON_DEATH: true,
        SKIN: 15
    }
});
