const dodge = (me, them, distance, interval) => {
          if (!them) return
          if (Math.abs(me.x - them.x) < 70 && Math.abs(me.y - them.y) < 70 && "bullet trap swarm drone minion crasher tank".includes(them.type) && them.team !== me.team) { 
          timer(() => {
             me.velocity.x += 50 * Math.sin(them.velocity.direction + (Math.PI/2)) * distance;
             me.velocity.y += 50 * Math.cos(them.velocity.direction + (Math.PI/2)) * distance;
            }, 12 * interval); //2-second dodge delay
         }
};
