function makeSanctuary(type) {
    let output = JSON.parse(JSON.stringify(type));
    output.PARENT = [defExports.dominator];
    for (let entry of Object.entries({
        SIZE: 30, //
        SKILL: setSkill(0, 0, 9, 9, 9, 9, 9, 0, 0, 0),
        CONTROLLERS: ['nearestDifferentMaster', 'spinWhileIdle'/*,'alwaysFire'*/],//alwaysFireMine
        CAN_BE_ON_LEADERBOARD: false,
        GIVE_KILL_MESSAGE: false,
        ACCEPTS_SCORE: false,
        AI: {
            FARMER: true,
            IGNORE_SHAPES: true
        }
    })) {
        output[entry[0]] = entry[1];
    }
    output.LABEL = "Sanctuary";
    if (type.PARENT[0].FACING_TYPE) {
        output.FACING_TYPE = type.PARENT[0].FACING_TYPE;
    }
    output.GUNS = [defExports.dominator.GUNS || [], type.PARENT[0].GUNS || [], type.GUNS || []].flat();
    output.TURRETS = [defExports.dominator.TURRETS || [], type.PARENT[0].TURRETS || [], type.TURRETS || []].flat();
    output.TURRETS = output.TURRETS || [];
    output.TURRETS.push({
        POSITION: [8, 0, 0, 0, 360, 1],
        TYPE: defExports.sanctuaryTurretMine
    }, {
        POSITION: [8, 0, 0, 0, 360, 1],
        TYPE: [defExports.medicS, {
            CONTROLLERS: ["dontTurn"]
        }]
    });
    output.HITS_OWN_TYPE = "pushOnlyTeam";
    return output;
};
