defExports.butaneGas = {
    PARENT: [defExports.bullet],
    MOTION_TYPE: 'glide',
    BODY: {
      HEALTH: 1000,
      SPEED: .1,
      RANGE: 500,
      DAMAGE: 0
    },
    INVISIBLE: [0, 1, 0.2],
    ON_COLLIDE: (me, them) => {
        if(!them.doesTorch || me.variables.doneCollide)  return;
        me.kill()
        me.variables.doneCollide = true
        let gun = me.master.guns[0]
        let ogCanShoot = gun.canShoot
        gun.canShoot = true
        fireGun(gun)
        let child = gun.children[gun.children.length - 1]
        child.velocity.x = me.velocity.x*.75;
        child.velocity.y = me.velocity.y*.75;
        child.x = them.x
        child.y = them.y
        gun.canShoot = ogCanShoot;
    },
};
