defExports.shapeshifter = {
    PARENT: [defExports.genericTank],
    LABEL: 'Shapeshifter',
    SHAPE: 255,
    TOOLTIP: 'Kill enemy tanks to transform into them!',
    GUNS: [{
        POSITION: [18, 8, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.less_pen]),
            TYPE: defExports.bullet
        }
    }],
    ON_KILL: (me, them) => {
        if (them) {
            if (them.type === 'tank' && (them.isBot || them.isPlayer)) {
                const onKill = me.onKill;
                const skills = them.skill.raw;
                me.isShapeshifter = true

                let exportName = global.exportNames[them.index]
                me.define(defExports[exportName]);

                // This exists to fix skill cap issues
                if (defExports[exportName].SKILL_CAP === undefined) {
                    me.skill.setCaps([c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL]);
                }

                me.onKill = onKill;
                me.skill.set(skills);

                // This exists to ensure that you won't gain free skill points when killing a Smasher 
                me.skill.points = 0;

                // Helicopter fix
                me.settings.isHelicopter = defExports[exportName].IS_HELICOPTER || null

                me.upgrades = [];
                me.labelOverride = "Shapeshifter"
                me.childrenMap.forEach(child => {
                    child.kill();
                });
            }
        }
    }
};
