function displayVE(me, value, max) {
    if (me.voidEnergy === undefined) {
        me.voidEnergy = value
    }
    me.maxVoidEnergy = max
    me.displayText = `Void Energy ${me.voidEnergy}/${max}`
}
function addVE(me, amount) {
    me.voidEnergy = Math.min(me.voidEnergy + (amount | 0), me.maxVoidEnergy)
    displayVE(me, 0, me.maxVoidEnergy)
}
function useVE(me, amount) {
    me.voidEnergy = Math.max(me.voidEnergy - (amount | 0), 0)
    displayVE(me, 0, me.maxVoidEnergy)
}
defExports.voidshield = {
    PARENT: [defExports.genericTank],
    LABEL: 'Void Shield',
    SHAPE: 5,
    TOOLTIP: "Gain void energy by dealing damage to passively negate damage. Beware of poison.",
    PROPS: [
        makeShell()
    ],
    ON_DEFINED: function (me) {
        displayVE(me, 0, 300)
    },
    ON_DEALT_DAMAGE: function (me, them) {
        addVE(me, 10)
    },
    ON_DAMAGED: function (me, them, amount) {
        if (amount <= 0) return;
        if (me.health.amount < me.health.max) {
            me.health.amount += Math.min(amount, me.voidEnergy)
            useVE(me, amount)
        } else if (me.shield.amount < me.shield.max) {
            me.shield.amount += Math.min(amount, me.voidEnergy)
            useVE(me, amount)
        }
    }
};
