const infatuate = (me, them, multiplier, duration, max) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode/* && !them.variables.infatuated*/) {
        //them.variables.infatuated = true;
        //setTimeout(() => {
        //    them.variables.infatuated = false;
        //}, 2.5 * duration * 1000);  
        timer(() => {
            //if (them.variables.infatuated) {
            them.shield.regenerate(-1);
            for (let i = 0; i < max; i++) {
                if (i !== max) them.damage /= ((1.2 * i) * multiplier);
            }
          //}
        }, 2.5 * duration);
    }
};
const infatuateII = (me, them, multiplier, duration, max) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode) timer(() => {
        them.shield.regenerate(-1);
    for (let i = 0; i < max; i++) {
        if (them && max < i) {
           them.damageReceived *= 5;
        }
    }
  }, 1.5 * duration);
};
