const addict = (me, them, multiplier, duration, team) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && them.team != team && !them.variables.onfire) {
        let oddu = them.onDealtDamageUniv || (() => { });
        infatuate(me, them, 1, 1, 12);
        them.onDealtDamageUniv = (me2, them2) => {
            if (me2 && them2) {
                if (oddu) oddu();
                infatuate(me2, them2, 1, 1, 12)
            }
        }
        setTimeout(() => {
            them.onDealtDamageUniv = oddu;
        }, 2 * duration * 1000);
    }
};
