const attract = (me, them, multiplier) => {
        /*me.distanceVar = (me.x - them.x) * (me.x - them.x) + (me.y - them.y) * (me.y - them.y);
        me.aVar = 1 * me.SIZE * them.SIZE / me.distanceVar;
        them.velocity.x += me.aVar;
        them.velocity.y += me.aVar;*/
        if (!them.invuln && !them.abilityImmune && !them.godmode && !them.passive && them.density < 10) {
        me.gravityMultiplier = 0.375;
        if(me.x - them.x > 0 && me.x - them.x != 0) {
        me.distanceVarX = (me.x - them.x) * (me.x - them.x)
        } else {me.distanceVarX = -((me.x - them.x) * (me.x - them.x))}
        if(me.y - them.y > 0 && me.y - them.y != 0) {
        me.distanceVarY = (me.y - them.y) * (me.y - them.y)
        } else {me.distanceVarY = -((me.y - them.y) * (me.y - them.y))}
        me.aVarX = me.gravityMultiplier * (me.SIZE + them.SIZE) / me.distanceVarX;
        me.aVarY = me.gravityMultiplier * (me.SIZE + them.SIZE) / me.distanceVarY;
        them.velocity.x += (me.aVarX / 2) * multiplier;
        them.velocity.y += (me.aVarY / 2) * multiplier;
    }
};
