const makeTeamSwitcher = (team, name) => {// merci Red!
    defExports["TeamChanger"+name] = {
        PARENT: [defExports.developer_parent],
        LABEL: "Change to " + name,
        COLOR: typeof team == "string" ? 2 : getTeamColor(team),
        ON_DEFINED: (me) => {
            me.team = -team
            if (me.socket.player.team) {
                me.socket.player.team = team
                me.socket.rememberedTeam = team
            }
        }
    };
}
for (let i = 0; i < teamNames.length; i++) {
    makeTeamSwitcher(i+1, teamNames[i])
}
