defExports.trueBlackHoleAura = {
    MUTATION: 'Aura',
    PARENT: [defExports.bullet],
    ALPHA: 0.3,
    //SHAPE: 1,
    ON_COLLIDE: (me, them) => {
        them.varX = Math.abs(me.x - them.x);
        them.varY = Math.abs(me.y - them.y);
        them.totalVar = Math.sqrt(Math.pow(them.varX, 2) + Math.pow(them.varY, 2))
        //attraction (note: utiliser un .abs? )
        them.attraction2 = them.gravForce / them.SIZE;
        them.gravForce = 15 * ((me.SIZE * them.SIZE) / Math.pow(them.totalVar, 2));//coeff
        them.direction = Math.atan2(me.x - them.x, me.y - them.y)
        them.velocity.x += Math.sin(them.direction) * them.gravForce;
        them.velocity.y += Math.cos(them.direction) * them.gravForce;
        //note: ne jamais mettre .cos à la place de .sin tu est trop bête -_- -_- (not au futur moi laisser ce commentaire pour d'autres choses que je vais faire)
    }
}
defExports.blackHoleAura = {
    MUTATION: 'SourceAuraOnCollide',
    PARENT: [defExports.bullet],
    ALPHA: 0.3,
    //SHAPE: 1,
    ON_DEALT_DAMAGE: (me, them) => {
        /*me.distanceVar = (me.x - them.x) * (me.x - them.x) + (me.y - them.y) * (me.y - them.y);
        me.aVar = 1 * me.SIZE * them.SIZE / me.distanceVar;
        them.velocity.x += me.aVar;
        them.velocity.y += me.aVar;*/
        me.gravityMultiplier = 0.2
        if(me.x - them.x > 0 && me.x - them.x != 0) {
        me.distanceVarX = (me.x - them.x) * (me.x - them.x)
        } else {me.distanceVarX = -((me.x - them.x) * (me.x - them.x))}
        if(me.y - them.y > 0 && me.y - them.y != 0) {
        me.distanceVarY = (me.y - them.y) * (me.y - them.y)
        } else {me.distanceVarY = -((me.y - them.y) * (me.y - them.y))}
        me.aVarX = me.gravityMultiplier * me.SIZE * them.SIZE / me.distanceVarX;
        me.aVarY = me.gravityMultiplier * me.SIZE * them.SIZE / me.distanceVarY;
        them.velocity.x += me.aVarX;
        them.velocity.y += me.aVarY;
    }
}
