const makeHealer = (type, name, options = {}) => {
    let output = deepCopy(type),
        stats = options.stats || [g.blank];
    applyStats(output.GUNS, [g.healer, ...stats], {
        shootEdit: (prop) => {
            let bulletExport = makeExportName(prop.TYPE, 'healThing');

            if (!defExports[bulletExport]) {
                defExports[bulletExport] = deepCopy(prop.TYPE);
                defExports[bulletExport].HITS_OWN_TEAM = true;
                defExports[bulletExport].TURRETS = [{
                   POSITION: [10, 0, 0, 0, 0, 1],
                   TYPE: [defExports.eggBossCircleProp, {
                       COLOR: 12
                    }]
               }];
        }
            prop.TYPE = defExports[bulletExport];
        }
    });
    output.TURRETS = output.TURRETS || [];
    output.TURRETS.push({
        POSITION: [12, 0, 0, 0, 360, 1],
        TYPE: [defExports.medicS, {
            CONTROLLERS: ["dontTurn"]
        }]
    });
    output.DANGER = 4;
    output.LABEL = name || `Healing ${output.LABEL}`;
    output.IS_HEALER = true;
    if (type.STAT_NAMES = statNames.lancer) {
      output.IS_HEALER = false,
      output.IS_INJECTOR = true;
    };
    return output;
};
