defExports.HBBullet = {
    PARENT: [defExports.bullet],
    ON_DEALT_DAMAGE: function (me, them) {
        //if (them.shield.amount > them.SHIELD) {them.shieldCapped = them.SHIELD} else {them.shieldCapped = them.shield.amount}
        if (them.shield.amount > them.SHIELD) {them.shield.amount = them.SHIELD}
        if(them.SHIELD != 0) {them.health.amount -= (them.SHIELD - them.shield.amount) * me.damage} else {them.health.amount -= me.damage * 4}
        if(them.shield.amount < them.SHIELD) {them.shield.amount += me.damage * 2.5}
    }
};
