const Changereload = (them) => {
    if (!them) return
    if (!them.passive) {
        them.skill.rld = 0.0001;
    }
};
const brostopshooting = (them) => {
    if (!them) return
    if (!them.passive) {
        them.skill.rld = Infinity;
    }
};
const Imfastasfuckboi = (them) => {
    if (!them) return
    if (!them.passive) {
        them.skill.rld = 3;
    }
};
