defExports.shinitatorBullet = {
    PARENT: [defExports.cooldefinebasebullet],
    ON_COLLIDE: (me , them) => {
    if(!them.isShiny) {
       them.isShiny = true
       them.color = 1//-1
       them.skill.score *= 3
       them.SIZE += 2
       them.label = "Shiny "+them.label
       them.settings.givesKillMessage = true
       me.kill()
    }}
}
defExports.darwinBullet = {
    PARENT: [defExports.cooldefinebasebullet],
    ON_DEALT_DAMAGE: (me , them) => {
            if (!them.isAlive()) {
                return
            }
            let options = [];
            let chances = [];
            for (let arr of them.EVOLUTIONS) {
                options.push(arr[0])
                chances.push(arr[1])
            }
            /*if (Math.random() < c.EVOLVE_HALT_CHANCE) {
                return
            }*/
            them.define(Class[options[ran.chooseChance(...chances)]])
            me.kill()
        
    }         
               } 
               
    
