function getAtomTurrets(atom) {
    let output = []
    output.push({
        POSITION: [40, 0, 0, 0, 0, 0],
        TYPE: defExports.atomBase
    })
    if (atom > shell1) {output.push({
        POSITION: [40*2, 0, 0, 0, 0, 0],
        TYPE: defExports.atomBase
    })}
    if (atom > shell1 + shell2) {output.push({
        POSITION: [40*3, 0, 0, 0, 0, 0],
        TYPE: defExports.atomBase
    })}
    if (atom > shell1 + shell2 + shell3) {output.push({
        POSITION: [40*4, 0, 0, 0, 0, 0],
        TYPE: defExports.atomBase
    })}
    if (atom > shell1 + shell2 + shell3 + shell4) {output.push({
        POSITION: [40*5, 0, 0, 0, 0, 0],
        TYPE: defExports.atomBase
    })}
    if (atom > shell1 + shell2 + shell3 + shell4 + shell5) {output.push({
        POSITION: [40*6, 0, 0, 0, 0, 0],//so I heard You Like Random Intervals, Here's Some
        TYPE: defExports.atomBase
    })}
    if (atom > shell1 + shell2 + shell3 + shell4 + shell5 + shell6) {output.push({
        POSITION: [40*7, 0, 0, 0, 0, 0],
        TYPE: defExports.atomBase
    })}
    if (atom > shell1 + shell2 + shell3 + shell4 + shell5 + shell6 + shell7) {output.push({
        POSITION: [40*8, 0, 0, 0, 0, 0],
        TYPE: defExports.atomBase
    })}
    for (let i = 0; i < atom; i++) {
        if (i < shell1) {
         output.push({
            POSITION: [9.5, 20, 0, 360 * (i/shell1), 210, 1],
            TYPE: defExports.particleElectron
        })
        }
        if (i < shell1 + shell2 && i+1 > shell1) {
            output.push({
               POSITION: [9.5, 40, 0, 360 * (i/shell2), 210, 1],
               TYPE: defExports.particleElectron
           })
           }
        if (i < shell1 + shell2 + shell3 && i+1 > shell1 + shell2) {
            output.push({
               POSITION: [9.5, 60, 0, 360 * (i/shell3), 210, 1],
               TYPE: defExports.particleElectron
           })
           }
        if (i < shell1 + shell2 + shell3 + shell4 && i+1 > shell1 + shell2 + shell3) {
            output.push({
               POSITION: [9.5, 80, 0, 360 * (i/shell4), 210, 1],
               TYPE: defExports.particleElectron
           })
           }
           if (i < shell1 + shell2 + shell3 + shell4 + shell5 && i+1 > shell1 + shell2 + shell3 + shell4) {
            output.push({
               POSITION: [9.5, 100, 0, 360 * (i/shell5), 210, 1],
               TYPE: defExports.particleElectron
           })
           }
           if (i < shell1 + shell2 + shell3 + shell4 + shell5 + shell6 && i+1 > shell1 + shell2 + shell3 + shell4 + shell5) {
            output.push({
               POSITION: [9.5, 120, 0, 360 * (i/shell6), 210, 1],
               TYPE: defExports.particleElectron
           })
           }
           if (i < shell1 + shell2 + shell3 + shell4 + shell5 + shell6 + shell7 && i+1 > shell1 + shell2 + shell3 + shell4 + shell5 + shell6) {
            output.push({
               POSITION: [9.5, 140, 0, 360 * (i/shell7), 210, 1],
               TYPE: defExports.particleElectron
           })
           }
    }
    return output
}
for (let i = 0; i < 118; i++) {
    defExports["atom" + i] = {
        PARENT: [defExports.genericTank],
        FACING_TYPE: 'autospin',
        COLOR: i % 46,
        BODY: {
            HEALTH: 12.5 * i,
            DAMAGE: 1.5 * Math.sqrt(i),
            SPEED: Math.max((base.SPEED * 1.5) - Math.sqrt(i), base.SPEED * 0.4),
            ACCELERATION: base.ACCEL * 1.25,
            FOV: 1.3,
            REGEN: 0.1
        },
        LABEL: atomNames[i],
        SIZE: 0.1 * i + 10,
        TOOLTIP: i > 81 ? "U.N.S.T.A.B.L.E. S.T.A.T.E." : null,
        ON_DEFINED: (me) => {
            me.number = i
            me.radioactivity = 0//hell ya
            me.nd = i-1
        },
        ON_TICK: (me) => {
            if (me.number > 81) {
                me.radioactivity += 1
                if (me.radioactivity > 500 * Math.random() + 600) {
                    me.define(Class["atom" + me.nd])
                }
            }
        },
        TURRETS: getAtomTurrets(i + 1),
    }
}
let atoms = []
atoms.push(defExports.molecularLiason)
for (let i = 0; i < 118; i++) {
    atoms.push(defExports["atom" + i])
}
branch("atomMania", "Atom Mania", atoms)
