defExports.newtonAura = {
    MUTATION: 'Aura',
    PARENT: [defExports.bullet],
    ALPHA: 0,
    ON_COLLIDE: (me, them) => {
        //if(them.newtonTimerCollide == null) {them.newtonTimerCollide = 0}
        if(them.type === "bullet" || them.type === "swarm" || them.type === "drone" || them.type === "minion" || them.type === "trap") {
        them.team = me.master.team
    if(them.SIZE < 10) {
        /*them.varX = Math.abs(me.x - them.x);
        them.varY = Math.abs(me.y - them.y);
        them.totalVar = Math.sqrt(Math.pow(them.varX, 2) + Math.pow(them.varY, 2))
        them.attraction2 = them.gravForce / them.SIZE;
        them.gravForce = -15 * ((me.SIZE * them.SIZE) / Math.pow(them.totalVar, 2));//coeff
        them.direction = Math.atan2(me.x - them.x, me.y - them.y)
        them.velocity.x += Math.sin(them.direction) * them.gravForce;
    them.velocity.y += Math.cos(them.direction) * them.gravForce
    
    basically the black hole*/

    them.velocity.y = -them.velocity.y
    them.velocity.x = -them.velocity.x
}
        else {
            if(!me.repulse) {
            //them.newtonTimerCollide += 1
            them.varX = Math.abs(me.x - them.x);
            them.varY = Math.abs(me.y - them.y);
            them.totalVar = Math.sqrt(Math.pow(them.varX, 2) + Math.pow(them.varY, 2))
            //if (them.totalVar > 50) {them.totalVar = 1}
            them.attraction2 = them.gravForce / them.SIZE;
            them.gravForce = -15 * ((me.SIZE * them.SIZE) / Math.pow(them.totalVar, 2));//coeff
            them.direction = Math.atan2(me.x - them.x, me.y - them.y)
            them.velocity.x += Math.sin(them.direction) * them.gravForce;
            them.velocity.y += Math.cos(them.direction) * them.gravForce;
            } else {
                //return to sender
            }
        }}
    },
    ON_TICK: (me) => {
        if(me.thing == null) {me.thing = 0}
        me.thing += 1
        if (me.thing > 150) {
            me.repulse = 1
        }
    }
}
