const headache = (me, them, multiplier, chance) => {
    if (!them) return
    if (Math.floor(Math.random() * 101) + 1 < chance && (them.type == 'tank' || them.type == 'miniboss') && !them.variables.pepperspray && them.socket) {
        me.damage *= multiplier * 3;
        me.source.sendMessage('Headshot landed!');
        them.sendMessage(me.source.name + ' landed a headshot on you!');
        them.variables.pepperspray = true;
        them.socket.talk('pepperspray', true, (multiplier / 2));
        setTimeout(() => {
            them.variables.pepperspray = false;
            them.socket.talk('pepperspray', false, (multiplier / 2));
        }, duration * 1000);
    }
};
