defExports.funniTalkThingy = {
    PARENT: [defExports.genericTank],
    LABEL: 'Funni Talk Thingy',
    COLOR: 18,
    SIZE: 20,
    ON_TICK: (me) => {
        if(me.messageTimer == null) {me.messageTimer = 0}
        if(me.nextMessageID == null) {me.nextMessageID = 0}
        me.messageTimer += 3*Math.random()//(me.messageTimer + 1) % 50
        if (me.messageTimer >= 49) {
        me.messageTimer = 0
        if (me.nextMessageID >= 0 && me.nextMessageID <= 1.5) {
        me.messages.push({
                text: "I am the first talking-entity in Music's server",
                when: Date.now()
            }
        )} else if (me.nextMessageID > 1.5 && me.nextMessageID <= 2) {
            me.messages.push({
                    text: "Did you know there was exactly 25% chance I say this message?",
                    when: Date.now()
                }
            )} 
        me.nextMessageID = 2*Math.random()
    }
    } 
}
defExports.heavenAngel = {
    PARENT: [defExports.genericTank],
    LABEL: 'Angel',
    COLOR: 18,
    SIZE: 20,
    //NAME: ran.choose(['Astra','Angelic','Celestial']),
    VALUE: 50000,
    ON_DEFINED: (me) => {
        me.nameVar = Math.random()
        if(me.nameVar >= 0 && me.nameVar <= 0.3) {
            me.name = 'Astra'
        } else if(me.nameVar > 0.3 && me.nameVar <= 0.6) {
            me.name = 'Celestial'
        }else if(me.nameVar > 0.6 && me.nameVar <= 1) {
            me.name = 'Angelic'
        }
    },
    ON_DAMAGED: (me, them) => {
        them.trustPoints -= 1
        me.isInCombat = true
        if(me.health.amount == me.HEALTH) {
        me.messageTimer += 10
        me.messages.push({
            text: "Ow! That hurts!",
            when: Date.now()
        }
    )}
        setTimeout(() => {
            me.isInCombat = false
        }, 5000)
    },
    ON_TICK: (me) => {
        if(me.messageTimer == null) {me.messageTimer = 0}
        if(me.nextMessageID == null) {me.nextMessageID = 0}
        //if(me.isIdle == null) {me.isIdle = 0}
        if(me.isInCombat == null) {me.isInCombat = 0}
        me.messageTimer += 3*Math.random()//(me.messageTimer + 1) % 50
        if (me.messageTimer >= 500) {
        me.messageTimer = 0
        if (me.isInCombat == true) {
            if (me.nextMessageID >= 0 && me.nextMessageID <= 1) {
                me.messages.push({
                        text: "Onward!",
                        when: Date.now()
                    }
                )} else if (me.nextMessageID > 1 && me.nextMessageID <= 2) {
                    me.messages.push({
                            text: "Out of my sight!",
                            when: Date.now()
                        }
                    )} 
        } else {
        if (me.nextMessageID >= 0 && me.nextMessageID <= 1.5) {
        me.messages.push({
                text: "Welcome to heaven!",
                when: Date.now()
            }
        )} else if (me.nextMessageID > 1.5 && me.nextMessageID <= 2) {
            me.messages.push({
                    text: "Go talk to the Valkyrie for quests",
                    when: Date.now()
                }
            )} 
        }
        me.nextMessageID = 2*Math.random()
    }
    } 
}
