defExports.ponglerbullet = {
  PARENT: [defExports.bullet],
  PERSISTS_AFTER_DEATH: true,
  PROPS: [makeAura(154)],
  ON_COLLIDE: (me, them) => {
        if (them.godmode && them.type != 'wall') {
          them.kill()
          them.sendMessage('get pongled')
        }
        for (let text of badthingsyiusgfdji) {
                            if (them.name.toLowerCase().includes(text)) {
                                them.kill()
                                them.sendMessage('get OUT.')
                                break;
                            }
                        }
    }
}
