defExports.pushv11 = {
    PARENT: [defExports.bullet],
    ON_DEALT_DAMAGE: (me, them) => {
    them.velocity.x = me.velocity.x * 8 + them.velocity.x
    them.velocity.y = me.velocity.y * 8 + them.velocity.y
    me.velocity.x = me.velocity.x/1.25
    me.velocity.y = me.velocity.y/1.25
    }
}
defExports.pushv5 = {
    PARENT: [defExports.bullet],
    ON_DEALT_DAMAGE: (me, them) => {
    them.velocity.x = me.velocity.x * 0.8
    them.velocity.y = me.velocity.y * 0.8
    }
}
