// Prerequisites - Modification
const laceration = (me, them, multiplier, once) => {
    if (!me.variables.hitList) me.variables.hitList = []
    if (!them) return
    if (me.variables.hitList.includes(them)) {them.damageReceived = -them.damageReceived; return}
    let trueDamage = them.health.max * multiplier
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && them.team != me.team && trueDamage > them.damageReceived) {
        them.damageReceived = -them.damageReceived
        me.variables.hitList.push(them)
        them.damageReceived = trueDamage
    }
};
