// Latest Tier 8 - Modification
defExports.imitator2 = {
    PARENT: [defExports.genericTank],
    LABEL: 'Joker',
    SHAPE: 255,
    TOOLTIP: 'Deal damage to enemy tanks to transform into them. Then press Q to switch back again!',
    GUNS: [{
        POSITION: [18, 8, 1, 0, 0, 0, 0],
        PROPERTIES: {
            SHOOT_SETTINGS: combineStats([g.basic, g.double_health, g.more_power, g.more_power, g.faster]),
            TYPE: defExports.bullet
        }
    }],
    TURRETS: [{
        POSITION: [10, 0, 0, 0, 0, 1],
        TYPE: [defExports.eggBossCircleProp, {
            COLOR: 243
        }]
    }],
    ON_DEALT_DAMAGE_UNIVERSAL: (me, them) => {
        if (them) {
            if (them.type === 'tank' && !me.isShapeshifter && !them.protected2) {
                const onKill = me.onKill;
                const skills = them.skill.raw;
                const oldskills = me.skill;
                const color = me.color;
                me.isShapeshifter = true

                let exportName = global.exportNames[them.index]
                me.define(defExports[exportName]);

                // This exists to fix skill cap issues
                if (defExports[exportName].SKILL_CAP === undefined) {
                    me.skill.setCaps([c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL, c.MAX_SKILL]);
                }

                me.onKill = onKill;
                //me.skill.set(skills);

                // This exists to ensure that you won't gain free skill points when killing a Smasher 
                me.skill.points = 0;

                // Helicopter fix
                me.settings.isHelicopter = defExports[exportName].IS_HELICOPTER || null

                me.labelOverride = me.label + " Joker"
                me.childrenMap.forEach(child => {
                    child.kill();
                });

                me.upgrades = [];

                me.isShapeshifter = true

                me.color = color

                me.onQ = (me2) => {
                    delete me.isShapeshifter
                    me2.upgradeTank(Class.imitator2)
                    me2.skill = oldskills
                    me2.skill.setCaps([9, 9, 9, 9, 9, 9, 9, 9, 9, 9]);
                }
            }
        }
    }
}
