             me.y = 4500/2
             me.randomSpeed = Math.random() * 0.5 + 0.7
             me.health.amount = me.health.max - (Math.random() * me.health.max) // can spawn with half HP 
             me.DAMAGE = Math.random() * me.DAMAGE + me.DAMAGE / 2
