    const makeRelic = (type, scale = 1, gem, SIZE) => { // Inspired by open source arras.io
        let relicCasing = {
            //PARENT: [defExports.genericEntity],
            LABEL: 'Relic Casing',
            COLOR: type.COLOR,
            MIRROR_MASTER_ANGLE: true,
            SHAPE: [[-0.4,-1],[0.4,-0.25],[0.4,0.25],[-0.4,1]].map(r => r.map(s => s * scale))
        }, relicBody = {
            //PARENT: [defExports.genericEntity],
            LABEL: 'Relic Mantle',
            COLOR: type.COLOR,
            MIRROR_MASTER_ANGLE: true,
            SHAPE: type.SHAPE
        };
        defExports[Math.random().toString(36)] = relicCasing;
        defExports[Math.random().toString(36)] = relicBody;
        let width = 6 * scale,
            y = 8.25 + ((scale % 1) * 5),
            isEgg = type.SHAPE == 0,
            casings = isEgg ? 8 : type.SHAPE,
            fraction = 360 / casings,
            GUNS = [],
            TURRETS = [{ POSITION: [32.5, 0, 0, 0, 0, 0], TYPE: [relicBody, {COLOR: type.COLOR}] }],
            PARENT = [type],
            additionalAngle = type.SHAPE % 2 === 0 ? 0 : fraction / 2;

        if (SIZE) {
            PARENT.push({ SIZE });
        }

        for (let i = 0; i < casings; i++) {
            let angle = i * fraction,
                gunAngle = angle + additionalAngle;
            if (isEgg) {
                GUNS.push({
                    POSITION: [4, width, 2.5, 12,  0, gunAngle, 0]
                });
                TURRETS.push({
                    POSITION: [8, -15,  0, angle, 0, 1],
                    TYPE: relicCasing
                }); 
            } else {
                GUNS.push({
                    POSITION: [4, width, 2.5, 12,  y, gunAngle, 0]
                });
                GUNS.push({
                    POSITION: [4, width, 2.5, 12, -y, gunAngle, 0]
                });
                TURRETS.push({
                    POSITION: [8, -15,  y, angle, 0, 1],
                    TYPE: relicCasing
                });
                TURRETS.push({
                    POSITION: [8, -15, -y, angle, 0, 1],
                    TYPE: relicCasing
                });
            }
        }

        if (gem) {
            TURRETS.push({
                POSITION: [8, 0, 0, 0, 0, 1],
                TYPE: [gem, { MIRROR_MASTER_ANGLE: true }]
            });
        }

        return {
            PARENT,
            LABEL: type.LABEL + ' Relic',
            COLOR: 8, // This is the color of the floor, this makes it look hollow.
            BODY: {
                ACCELERATION: 0.001
            },
            CONTROLLERS: [],
            VALUE: type.VALUE * 100_000,
            GIVE_KILL_MESSAGE: true,
            GUNS,
            TURRETS
        };
    }

    const rarePolygons1 = ["egg", "square", "triangle", "pentagon", "betaPentagon", "alphaPentagon", "hexagon"]
    const rarePolygons2 = ["shiny", "legendary", "misshapen", "shadow", "misscolored", "rainbow", "trans", "mythical", "sacred", "albino", "epilepsy","titanic","magic","ghost","heavy","sticky"]

    for (let i = 0; i < rarePolygons2.length; i++) {
        for (let j = 0; j < rarePolygons1.length; j++) {
            defExports[rarePolygons2[i]+rarePolygons1[j]] = makeRare(rarePolygons1[j], i)
        }
    }
    const labyPolygons = ["lbeta","lalpha","lomega","lgamma","ldelta","lultra"]
    const rarePolygonsWithoutPentas = ["egg", "square", "triangle", "pentagon", "hexagon"]
    for (let i = 0; i < rarePolygons2.length; i++) {
        for (let j = 0; j < labyPolygons.length; j++) {
            for (let h = 0; h < rarePolygonsWithoutPentas.length; h++) {defExports[labyPolygons[j]+rarePolygons2[i]+rarePolygonsWithoutPentas[h]] = makeRare(labyPolygons[j]+rarePolygonsWithoutPentas[h], i)
            }
        }
    }
    const relics = []

    for (let [gemColor, name] of [
        [-1, "Brilliant"], // Cyan
        [13, "Power"], // Yellow
        [165, "Space"], // Orange
        [12, "Reality"], // Red
        [10, "Soul"], // Blue
        [32, "Time"], // Orange
        [11, "Mind"], // Green
        [19, "Aether"], // Extra Black
        [1, "Life"], // Lime
        ["0", ""], // Custom
    ]) {
        let gem;
        if (gemColor) {
            gem = defExports[name + "Gem"] = {
                PARENT: ['gem'],
                LABEL: name + ' Gem',
                SHAPE: 6,
                COLOR: gemColor
            }
        }

        defExports[name + "relicegg"] = makeRelic(defExports.egg, 0.5, gem, 7);
        defExports[name + "relicsquare"] = makeRelic(defExports.square, 1, gem);
        defExports[name + "relictriangle"] = makeRelic(defExports.triangle, 1.45, gem);
        defExports[name + "relicpentagon"] = makeRelic(defExports.pentagon, -0.6, gem);
        defExports[name + "relicbetaPentagon"] = makeRelic(defExports.betaPentagon, -0.6, gem);
        defExports[name + "relicalphaPentagon"] = makeRelic(defExports.alphaPentagon2, -0.6, gem); // Has weird visual effects
        defExports[name + "relichexagon"] = makeRelic(defExports.hexagon, -0.6, gem);
        defExports[name + "relicheptagon"] = makeRelic(defExports.heptagon2, -0.7, gem)

        relics.push(
            name + "relicegg",
            name + "relicsquare",
            name + "relictriangle",
            name + "relicpentagon",
            name + "relicbetaPentagon",
            name + "relicalphaPentagon",
            name + "relichexagon",
            name + "relicheptagon"
        )
    }

