function doLancerThing(my) {
    if (my.IS_SMASHER) {
        return;
    }
    my.IS_LANCER = true;
    for (let key in my) {
        if (key.startsWith("UPGRADES_TIER")) {
            my[key].forEach(doLancerThing);
        }
    }
}

doLancerThing(defExports.lancer);
function doShipThing(my) {
    my.IS_SHIP = true;
    for (let key in my) {
        if (key.startsWith("UPGRADES_TIER")) {
            my[key].forEach(doShipThing);
        }
    }
}
doShipThing(defExports.ship);

function doSpikeThing(my) {
    my.HITS_OWN_TYPE = "spike";
    for (let key in my) {
        if (key.startsWith("UPGRADES_TIER")) {
            my[key].forEach(doSpikeThing);
        }
    }
}
