const upforce = (them, upness, duration) => {
    if (!them) return
    // normal tanks
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.up && !them.settings.isHelicopter) timer(() => {
        them.variables.up = true;
        them.LAYER += 15 + upness;
        them.settings.isHelicopter = true;
        setTimeout(() => {
        them.variables.up = false;
        them.LAYER -= (15 + upness);
        them.settings.isHelicopter = false;
        }, 4 * duration * 1000);
    }, 1.5);
    // helicopters 
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.up && them.settings.isHelicopter) timer(() => {
        them.variables.up = true;
        them.motionType = 'GLIDEBALL';
        setTimeout(() => {
        them.variables.up = false;
        them.motionType = 'glideBall';
        }, 4 * duration * 1000);
    }, 1.5);
};
