function makeFunnyFlail(label, codename, length, input = {}) {
    let options = {
        posdiff: [-1.5, 0, 0, 0, 0, 0],
        color: 16,
        gun: [25, 5, 1, 8, 0, 0, 0],
        endpiece: defExports.flailEnd,
        circlex: 1,
        finalPieceSpecificMap: [1, 1, 1, 1, 1, 1],
    }
    if (input.posdiff != null) options.posdiff = input.posdiff;
    if (input.color != null) options.color = input.color;
    if (input.gun != null) options.gun = input.gun;
    if (input.endpiece != null) options.endpiece = input.endpiece;
    if (input.circlex != null) options.circlex = input.circlex;
    for (let i = 0; i < length; i++) {
        defExports[codename + "Chain" + i] = {
            LABEL: 'Collision',
            BODY: {
                FOV: 1
            },
            COLOR: options.color,
            SYNC_TURRET_SKILLS: true,
            GUNS: [{
                POSITION: options.gun,
                PROPERTIES: {
                    COLOR: options.color
                }
            }],
            TURRETS: [{
                POSITION: (function () {
                    let out = [20, 30, 0, 0, 0, 1].map((item, j) => item + options.posdiff[j]);
                    if (i === 0) return out.map((item, j) => item * options.finalPieceSpecificMap[j]);
                    return out
                })(),
                TYPE: i === 0 ? options.endpiece : defExports[codename + "Chain" + (i - 1)]
            }]
        }
    }
    let FLAILSTURRETS = [];
    for (let i = 0; i < options.circlex; i++) {
        FLAILSTURRETS.push({
            POSITION: [6, 9, 0, 360 / options.circlex * i, 0, 0],
            TYPE: defExports[codename + "Chain" + (length - 1)]
        });
    }
    return {
        PARENT: [defExports.genericTank],
        LABEL: label,
        DANGER: 7,
        STAT_NAMES: statNames.flail,
        BODY: {
            SPEED: base.SPEED * .8,
            ACCELERATION: base.ACCEL * .9
        },
        TURRETS: FLAILSTURRETS
    }
};
