const energize = (them, a_multi, r_multi, duration) => {
    if (!them) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && !them.variables.ene) timer(() => {
        them.variables.ene = true;
        them.acceleration += 'food drone'.includes(them.type) ? (.02 * a_multi) : (2.5 * a_multi);
        them.reloadCoef *= (1.017 * r_multi);
        setTimeout(() => {
            them.variables.ene = false;
            them.acceleration -= 'food drone'.includes(them.type) ? (.02 * a_multi) : (2.5 * a_multi);
            them.reloadCoef /= (1.017 * r_multi);
        }, 4 * duration * 1000);
    }, 1.5);
};
