const excite = (me, them, a_multi, r_multi, duration, team) => {
    if (!them && !me.isDead()) return
    if (!them.immuneToAbilities && !them.invuln && !them.passive && !them.godmode && them.team != team && !them.variables.exc) {
        let oddu = them.onDealtDamageUniv || (() => { });
        energize(them, a_multi, r_multi, duration);
        them.variables.exc = true;
        them.onDealtDamageUniv = (me2, them2) => {
            if (me2 && them2) {
                if (oddu) oddu();
                energize(me2, them2, 1, 1, 1, team);
            }
        }
        setTimeout(() => {
            them.onDealtDamageUniv = oddu;
        }, 1.5 * duration);
    if (!them.variables.exc) {
        energize(me2, them2, 1, 1, 0, team);
        excite(me, them, 1, 1, 0, team);
        }
    }
};
