const chrono = (me, them, multiplier, duration) => {
    if (!them) return
    if (them.team !== me.team && them.LABEL !== 'Chronokinesis') timer(() => {
        them.velocity.x /= 1.05 * multiplier;
        them.velocity.y /= 1.05 * multiplier;
    }, 1.5 * duration);
};
